{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Scale each normalized input embedding by 1.25 when its nonpadding item appeared earlier in the visible causal context. This adds a deterministic repeat indicator while preserving embedding parameters, GRU topology, readout, loss, optimizer and routing. The generated predictor already imports the updated model class from train.py, so inference uses the same feature construction.",
      "edits": [
        {
          "find": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(torch.nn.functional.normalize(self.item_emb(seq), p=2, dim=-1))",
          "replace": "    def _input_embeddings(self, seq: torch.Tensor) -> torch.Tensor:\n        earlier = torch.ones(\n            (seq.size(1), seq.size(1)), dtype=torch.bool, device=seq.device\n        ).tril(diagonal=-1)\n        repeated = (\n            (seq.unsqueeze(2) == seq.unsqueeze(1)) & earlier.unsqueeze(0)\n        ).any(dim=-1) & seq.ne(0)\n        emb = torch.nn.functional.normalize(self.item_emb(seq), p=2, dim=-1)\n        emb = emb * (1.0 + 0.25 * repeated.to(emb.dtype)).unsqueeze(-1)\n        return self.dropout(emb)\n\n    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self._input_embeddings(seq)"
        },
        {
          "find": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(torch.nn.functional.normalize(self.item_emb(seq), p=2, dim=-1))",
          "replace": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self._input_embeddings(seq)"
        }
      ]
    }
  ],
  "change_summary": "Add causal repeat-occurrence input scaling consistently during training and prediction, preserving one GRU model per category and all existing training settings."
}
